def title_of(html: str) -> str:
    """Text between the first `<title>` and the next `</title>` in html, or "" if absent."""
    ex title_of("<html><head><title>Hello</title></head></html>") == "Hello"
    ex title_of("<p>no title</p>") == ""
    ex title_of("<title>unclosed") == ""
    ex title_of("") == ""
    _, sep, after = html.partition("<title>")
    if sep == "":
        return ""
    text, sep2, _ = after.partition("</title>")
    if sep2 == "":
        return ""
    return text.copy()

